script:
let find_product_button = root_element.querySelector(".btn-find-product");
let check_in_button = root_element.querySelector(".btn-check-in-item");
let check_out_button = root_element.querySelector(".btn-check-out-item");

find_product_button.addEventListener("click", () => {
    let d = new frappe.ui.Dialog({
        title: 'Enter product SKU',
        fields: [
            {
                label: 'Product',
                fieldname: 'product',
                fieldtype: 'Link',
                options: 'Ascend Product',
                description: 'Alternatively, you may find product locations by utilizing the "Find Product" button on any Ascend Product document view.'
            }
        ],
        size: 'small', // small, large, extra-large 
        primary_action_label: 'Submit',
        primary_action(values) {
            d.hide();
            bullwheel.warehouse.product_location_dialog({
        		product_sku: values.product
        	})
        }
    });
    d.show();
});

check_in_button.addEventListener("click", () => {
    bullwheel.warehouse.check_in_item();
});

check_out_button.addEventListener("click", () => {
    bullwheel.warehouse.check_out_item();
});

